actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate NM state additions
            double additions = 0.0;

            // NM requires addback of:
            // - Federal interest income (taxable to NM)
            // - Bonus depreciation (NM decouples from IRC § 168(k))
            // - IRC § 168(n) qualified property expensing
            // - IRC § 163(j) business interest deduction adjustments
            // - State income taxes deducted federally

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.bonus_depreciation_claimed;
            // additions += result.section_168n_deduction;
            // additions += result.section_163j_adjustment;
            // additions += result.state_taxes_deducted;

            apportionment.state_additions = additions;

            // Calculate NM state subtractions
            double subtractions = 0.0;

            // NM allows subtraction of:
            // - NM municipal bond interest (exempt for NM purposes)
            // - NM net operating loss deduction (if applicable)
            // - Certain dividend income (85% dividend received deduction)

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.nm_municipal_interest;
            // subtractions += result.nm_nol_deduction;
            // subtractions += result.dividend_received_deduction;

            apportionment.state_subtractions = subtractions;

            // NM uses 5.9% flat rate (effective 2025)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract NM state credits
            // NM offers various credits: job creation, rural area credits,
            // technology jobs, film production, renewable energy, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
